package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
)

type Input struct {
	Parts []string  `json:"parts"`
	Args  []string  `json:"args"`
	Index float64   `json:"index"`
}

func main() {
	var sysin Input
	b, err := io.ReadAll(os.Stdin)
	if err != nil {
		panic(err)
	}
	if err := json.Unmarshal(b, &sysin); err != nil {
		panic(err)
	}

	parts := sysin.Parts
	args := sysin.Args
	i := int(sysin.Index)

	if i < 0 {
		i = 0
	}
	if i >= len(parts) {
		i = len(parts) - 1
	}

	newParts := make([]string, 0, len(parts)+len(args))
	newParts = append(newParts, parts[:i+1]...)
	newParts = append(newParts, args...)
	newParts = append(newParts, parts[i+1:]...)

	result := newParts

	out, err := json.Marshal(result)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

type Input struct {
	Cmd     string `json:"cmd"`
	Service string `json:"service"`
}

func main() {
	var sysin Input
	b, err := io.ReadAll(os.Stdin)
	if err != nil {
		panic(err)
	}
	if err := json.Unmarshal(b, &sysin); err != nil {
		panic(err)
	}

	appCmd := sysin.Cmd
	serviceName := sysin.Service

	args := []string{"--abort-on-container-exit"}
	if serviceName != "" {
		args = append(args, "--exit-code-from", serviceName)
	}

	parts := strings.Fields(appCmd)
	inserted := false
	for i, p := range parts {
		if p == "up" {
			newParts := make([]string, 0, len(parts)+len(args))
			newParts = append(newParts, parts[:i+1]...)
			newParts = append(newParts, args...)
			newParts = append(newParts, parts[i+1:]...)
			parts = newParts
			inserted = true
			break
		}
	}

	var result string
	if inserted {
		result = strings.Join(parts, " ")
	} else {
		result = appCmd
	}

	out, err := json.Marshal(result)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))
}

